document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".slider__track"),t=document.querySelectorAll(".slider__item"),n=document.querySelector(".next-btn"),d=document.querySelector(".prev-btn");let s=0,c=0,r=!1;const o=()=>{e.style.transform=`translateX(-${100*s}%)`},a=e=>{r=!0,c=e.type.includes("mouse")?e.pageX:e.touches[0].clientX},l=e=>{if(!r)return;r=!1;const n=e.type.includes("mouse")?e.pageX:e.changedTouches[0].clientX,d=c-n;Math.abs(d)>50&&(s=d>0?Math.min(s+1,t.length-1):Math.max(s-1,0),o())};e.addEventListener("mousedown",a),e.addEventListener("mouseup",l),e.addEventListener("mouseleave",()=>r=!1),e.addEventListener("touchstart",a),e.addEventListener("touchend",l),n.addEventListener("click",()=>{s=(s+1)%t.length,o()}),d.addEventListener("click",()=>{s=(s-1+t.length)%t.length,o()})});